export function pieceArt(id, installed=false){
const gear=(cx,cy,r,n=12)=>Array.from({length:n},(_,i)=>'<rect x="'+(cx-5)+'" y="'+(cy-r-6)+'" width="10" height="14" rx="2" transform="rotate('+(i*360/n)+' '+cx+' '+cy+')" fill="#ad8244" stroke="#3a493a" stroke-width="1.5"/>').join('');
const shapes={
spring:'<path d="M42 79h15c-20-66 93-74 91-12s-79 53-77 8 57-40 55-5-35 30-35 4 17-19 17-5h56" fill="none" stroke="#344b4d" stroke-width="9"/><path d="M42 77h15c-20-66 93-74 91-12s-79 53-77 8 57-40 55-5-35 30-35 4 17-19 17-5h56" fill="none" stroke="#9cb1ad" stroke-width="4"/><path d="M40 71v14m125-23v14" stroke="#745c37" stroke-width="6"/>',
gear:gear(105,67,38)+'<circle cx="105" cy="67" r="36" fill="#cba259" stroke="#384837" stroke-width="2"/><circle cx="105" cy="67" r="27" fill="#534e35"/>'+[0,120,240].map(a=>'<path d="M100 67V40h10v27l23 13-5 9-23-13-23 13-5-9Z" transform="rotate('+a+' 105 67)" fill="#d9ba73"/>').join('')+'<circle cx="105" cy="67" r="10" fill="#856d43" stroke="#f0d696" stroke-width="2"/><circle cx="105" cy="67" r="4" fill="#293d35"/>',
bell:'<path d="M100 30v-7q0-9 7-9t7 9v7" fill="none" stroke="#7b6440" stroke-width="4"/><path d="M65 98q17-12 17-41q0-29 25-29t25 29q0 29 17 41Z" fill="#d9b565" stroke="#4c4b32" stroke-width="2.5"/><path d="M92 42q-6 22-8 43" fill="none" stroke="#f7df98" stroke-width="7" stroke-linecap="round"/><path d="M126 46q-1 30 12 47" fill="none" stroke="#a58040" stroke-width="6"/><ellipse cx="107" cy="98" rx="43" ry="8" fill="#8e6c37" stroke="#4c4b32" stroke-width="2"/><ellipse cx="107" cy="97" rx="34" ry="4" fill="#514a30"/><path d="M107 94v13" stroke="#ddc27d" stroke-width="4"/><circle cx="107" cy="109" r="6" fill="#b88f44"/>',
turbo: '<g transform="translate(86 75)"><g class="train-wheel train-driver">'+gear(0,0,31,10)+'<circle r="30" fill="#ac6045" stroke="#374638" stroke-width="2"/><circle r="20" fill="none" stroke="#e1b181" stroke-width="4"/><path d="M-22 0h44M0-22v44" stroke="#573f2e" stroke-width="5"/><circle r="6" fill="#e7c87e"/></g></g>'+
       '<g transform="translate(132 44)"><g class="train-wheel train-pinion">'+gear(0,0,21,9)+'<circle r="20" fill="#c99752" stroke="#374638" stroke-width="2"/><path d="M-15 0h30M0-15v30" stroke="#573f2e" stroke-width="5"/><circle r="4" fill="#e7c87e"/></g></g>',
hammer:'<path d="M70 106l58-65" stroke="#423e2e" stroke-width="15" stroke-linecap="round"/><path d="M70 103l56-62" stroke="#ba8250" stroke-width="9" stroke-linecap="round"/><path d="M105 33l13-16 45 34-13 17Z" fill="#78847a" stroke="#34463c" stroke-width="3"/><path d="M110 32l42 31m-36-40 40 32" stroke="#c0c8ad" stroke-width="2"/><path d="M114 49l12 9" stroke="#5b4530" stroke-width="7"/><circle cx="69" cy="105" r="3" fill="#f1cc8a"/>',
feather:'<path d="M67 111Q39 35 149 17Q161 90 67 111Z" fill="#517b8a" stroke="#304e48" stroke-width="2"/><path d="M62 120Q87 77 145 23" fill="none" stroke="#e2d6a9" stroke-width="3"/>'+[0,1,2,3,4].map(i=>'<path d="M'+(77+i*11)+' '+(96-i*14)+'l-13 -18m13 18 27 -5" fill="none" stroke="#a5bdba" stroke-width="1.5"/>').join('')
};
if(installed) return shapes[id];
return '<svg viewBox="0 0 210 140" aria-hidden="true"><ellipse cx="106" cy="122" rx="65" ry="8" fill="#39463314"/><g>'+shapes[id]+'</g><path d="M22 124h20m126 0h20" stroke="#998b65" stroke-width="1"/><text x="105" y="137" text-anchor="middle" font-size="6" letter-spacing="2" fill="#847b60">OFICINA BELLAMY</text></svg>'
}
